package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The terms a new claim is fixed with when it is created, and the due-by they give; a claim belongs to the period
 *  holding its due-by. */
public final class DueBy {

    private DueBy() {
    }

    /** The terms (business days) a new claim of the person dated on the date is fixed with: the person's own terms,
     *  else the terms of their grade in force on the date (else the sheet's terms in force on it). */
    public static int terms(Person person, LocalDate date, SettingRepository settings) {
        return person.terms() != null ? person.terms()
                : settings.termsFor(person.sheetId(), person.grades().on(date), date);
    }

    /** The due-by of a new claim of the person dated on the date: the terms-th business day after the date, skipping
     *  Saturdays, Sundays and the sheet's holidays as they are now. */
    public static LocalDate of(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.dueBy(person.sheetId(), date, terms(person, date, settings));
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** People by sheet, in list order: by their position in the list (new people go to the end). */
@Repository
public class PersonRepository {

    private static final RowMapper<Person> ROW = (rs, i) -> new Person(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getString("name"), null, rs.getLong("version"),
            rs.getInt("statement_count"), rs.getBigDecimal("stated_total"), rs.getObject("statement_date", LocalDate.class),
            rs.getObject("retired_from", LocalDate.class), Grades.NONE, Holds.NONE, (Integer) rs.getObject("terms"),
            rs.getString("contact"), List.of(), rs.getString("origin"), List.of(), rs.getString("tags"), List.of());

    private record GradeRow(long personId, Grades.Grade grade) {
    }

    private static final RowMapper<GradeRow> GRADE_ROW = (rs, i) -> new GradeRow(rs.getLong("person_id"),
            new Grades.Grade(rs.getString("grade"), rs.getObject("from_date", LocalDate.class)));

    private record HoldRow(long personId, Holds.Hold hold) {
    }

    private static final RowMapper<HoldRow> HOLD_ROW = (rs, i) -> new HoldRow(rs.getLong("person_id"),
            new Holds.Hold(rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));

    private record RetirementRow(long personId, Person.Retirement retirement) {
    }

    private static final RowMapper<RetirementRow> RETIREMENT_ROW = (rs, i) -> new RetirementRow(rs.getLong("person_id"),
            new Person.Retirement(rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
        LocalDate today = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
        Map<Long, List<Grades.Grade>> byPerson = jdbc.query(
                "SELECT * FROM person_grade WHERE sheet_id = ? ORDER BY person_id, from_date NULLS FIRST", GRADE_ROW,
                sheetId).stream().collect(Collectors.groupingBy(GradeRow::personId,
                        Collectors.mapping(GradeRow::grade, Collectors.toList())));
        Map<Long, List<Holds.Hold>> holdsByPerson = jdbc.query(
                "SELECT * FROM person_hold WHERE sheet_id = ? ORDER BY person_id, id", HOLD_ROW, sheetId).stream()
                .collect(Collectors.groupingBy(HoldRow::personId,
                        Collectors.mapping(HoldRow::hold, Collectors.toList())));
        Map<Long, List<String>> aliasesByPerson = aliases(sheetId, null);
        Map<Long, List<Person.Retirement>> retirementsByPerson = retirements(sheetId, null);
        Map<Long, List<Person.StatementLine>> statementsByPerson = jdbc.query(
                "SELECT person_id, due_total, statement_date FROM person_statement WHERE sheet_id = ? AND NOT cancelled "
                        + "ORDER BY person_id, id", STATEMENT_ROW, sheetId).stream()
                .collect(Collectors.groupingBy(StatementRow::personId,
                        Collectors.mapping(StatementRow::line, Collectors.toList())));
        return people.stream().map(p -> {
            Grades grades = new Grades(byPerson.getOrDefault(p.id(), List.of()));
            return new Person(p.id(), p.sheetId(), p.name(), grades.on(today), p.version(), p.statementCount(),
                    p.statedTotal(), p.statementDate(), p.retiredFrom(), grades,
                    new Holds(holdsByPerson.getOrDefault(p.id(), List.of())), p.terms(), p.contact(),
                    aliasesByPerson.getOrDefault(p.id(), List.of()), p.origin(),
                    retirementsByPerson.getOrDefault(p.id(), List.of()), p.tags(),
                    statementsByPerson.getOrDefault(p.id(), List.of()));
        }).toList();
    }

    /** Set the person's tags (joined by commas; null: none), keeping each among the tags ever used on the sheet. */
    public void tags(Person person, String tags) {
        jdbc.update("UPDATE person SET tags = ? WHERE sheet_id = ? AND id = ?", tags, person.sheetId(), person.id());
        if (tags != null) {
            for (String tag : tags.split(",")) {
                jdbc.update("MERGE INTO claim_tag KEY (sheet_id, tag) VALUES (?, ?)", person.sheetId(), tag);
            }
        }
            long id = ids.get(i);
            long position = i == at ? to + 1 : i == to ? at + 1 : i + 1;
            jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", position, person.sheetId(), id);
        }
        return to + 1;
    }

